ee:message.ee:set-payload:
%dw 2.0
output application/json

var getTA = payload
---
{
  id_transaccion: getTA.id_transaccion,
  CUS: getTA.CUS,
  atributos_pasarela: {
    pasarela: getTA.atributos_pasarela.pasarela,
    tipo_pasarela: getTA.atributos_pasarela.tipo_pasarela
  },
  metodo_pago: getTA.metodo_pago,
  referencias: {
    referencia: getTA.referencias.referencia,
    descripcion: getTA.referencias.descripcion,
    moneda: getTA.referencias.moneda,
    valor_pagar: getTA.referencias.valor_pagar,
    impuestos: (getTA.referencias.impuestos default []) map (impuesto) -> {
      tipo: impuesto.tipo,
      valor: impuesto.valor
    },
    detalle_referencias: (getTA.referencias.detalle_referencias default []) map (detalle) -> {
      referencia: detalle.referencia,
      numero_factura: detalle.numero_factura,
      Numero_Cuenta_Facturacion: detalle.Numero_Cuenta_Facturacion,
      descripcion: detalle.descripcion,
      moneda: detalle.moneda,
      valor_pagar: detalle.valor_pagar,
      impuestos: (detalle.impuestos default []) map (impuesto) -> {
        tipo: impuesto.tipo,
        valor: impuesto.valor
      },
      atributos: (detalle.atributos default []) map (atributo) -> {
        atributo: atributo.atributo,
        valor: atributo.valor
      }
    }
  },
  cliente: {
    tipo_documento: getTA.cliente.tipo_documento,
    numero_documento: getTA.cliente.numero_documento,
    nombre_completo: getTA.cliente.nombre_completo,
    correo: getTA.cliente.correo,
    telefono: getTA.cliente.telefono
  },
  concepto: getTA.concepto,
  entidad_bancaria: getTA.entidad_bancaria,
  estado_transaccion: getTA.estado_transaccion,
  fecha_registro: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"},
  fecha_respuesta_pasarela: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"}
}

%dw 2.0
output application/json
---
{
    attributes: [
        {
            key: "transactionId",
            value: vars.idTransaccion as String
        }
    ]
}

%dw 2.0
output application/json

fun fechaHoraColombia() =
  (now() >> "America/Bogota") as String {
    format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"
  }

var fechaColombia = fechaHoraColombia()

fun getEstadoPayu(statePol, responseCodePol) =
    do {
        var state = (statePol default "") as String
        var code = (responseCodePol default "") as String
        ---
        if (
            (["7", "12", "14"] contains state) and
            (["9994", "9995", "9996", "9999", "25"] contains code)
        )
            "EN_PROCESO"
        else if (state == "4" and code == "1")
            "PAGADA"
        else if (
            state == "6" and
            (["5", "8", "9", "12", "19", "9991"] contains code)
        )
            "RECHAZADA"
        else if (
            state == "6" and
            (["28", "35"] contains code)
        )
            "RECHAZADA"
        else if (
            state == "104" and
            (["9998", "1006", "1007"] contains code)
        )
            "RECHAZADA"
        else if (state == "5" and code == "9997")
            "RECHAZADA"
        else
            "NO_CONCILIADA"
    }

fun getEstadoWompi(status) =
    do {
        var state = upper((status default "") as String)
        ---
        if (state == "APPROVED")
            "PAGADA"
        else if (
            ["PENDING", "PENDING_VALIDATION"] contains state
        )
            "EN_PROCESO"
        else if (
            ["DECLINED", "ERROR", "VOIDED"] contains state
        )
            "RECHAZADA"
        else
            "NO_CONCILIADA"
    }

fun getEstadoPayuDisputa(status) =
    do {
        var state = upper((status default "") as String)
        ---
        if (state == "WON")
            "PAGADA"
        else if (
            ["LOST", "EXPIRED"] contains state
        )
            "RECHAZADA"
        else if (
            [
                "OPENED",
                "NOTIFIED",
                "DOCUMENTS_REQUIRED",
                "UNDER_REVIEW"
            ] contains state
        )
            "EN_PROCESO"
        else
            "NO_CONCILIADA"
    }

var statusWompi =
    vars.payloadRequest.data.transaction.status default null

var statusPayuDisputa =
    vars.payloadRequest.properties.state default null

var statePolPayu =
    vars.payloadRequest.state_pol default null

var responseCodePolPayu =
    vars.payloadRequest.response_code_pol default null

var estadoPago =
    if (statusWompi != null and statusWompi != "")
        getEstadoWompi(statusWompi)
    else if (statusPayuDisputa != null and statusPayuDisputa != "")
        getEstadoPayuDisputa(statusPayuDisputa)
    else if (
        statePolPayu != null or
        responseCodePolPayu != null
    )
        getEstadoPayu(
            statePolPayu,
            responseCodePolPayu
        )
    else
        "NO_CONCILIADA"

var referenciaTransaccion =
    vars.payloadRequest.data.transaction.id
        default vars.payloadRequest.transactionId
        default vars.payloadRequest.transaction_id
        default ""

---
{
  query: {
    update: "BOT_PAYMENT_GATEWAY",
    updates: [
      {
        q: {
          Referencia_Venta: payload.id_transaccion
        },
        u: {
          "\$set": {
            Estado: estadoPago,
            Referencia_Transaccion: referenciaTransaccion,
            Estado_Pagos_Online: "Actualizado exitosamente",
            Fecha_Actualizacion: fechaColombia
          }
        },
        multi: false
      }
    ]
  }
}

%dw 2.0
output application/json

---
{
    query: {
        update: "MDM_FACTURA_ONLINE",
        updates: [
            {
                q: {
                    numero_cuenta_facturacion: payload.referencias.detalle_referencias[0].Numero_Cuenta_Facturacion default "",
                    numero_factura: payload.referencias.detalle_referencias[0].numero_factura default ""
                },
                u: {
                    "\$set": {
                        estado_factura: "03"
                    }
                },
                multi: true,
                upsert: false
            }
        ]
    }
}

%dw 2.0
output application/json
---
{
    query: {
        find: "MDM_PAGOS_ONLINE",
        filter: {
            NumeroCuentaFacturacion: payload.referencias.detalle_referencias[0].Numero_Cuenta_Facturacion default "",
            NumeroFactura: payload.referencias.detalle_referencias[0].numero_factura default ""
        }
    }
}

%dw 2.0
output application/json

var origin =
    if (upper(payload.atributos_pasarela.pasarela default "") == "WOMPI")
        "BANCOLOMBIA"
    else
        payload.atributos_pasarela.pasarela default ""

---
{
    query: {
        find: "BOT_PARAMETERS",
        filter: {
            Code: "PARAMETERS_PAYMENT_GATEWAY",
            Origin: origin
        }
    }
}

%dw 2.0
output application/json

var opciones = payload.result[0].Values default []

var bancoEncontrado =
    (
        opciones filter ((item) ->
            upper(item.Code default "") ==
            upper(vars.entidadBancaria default "")
        )
    )[0] default null

var bancoDefecto =
    (
        opciones filter ((item) ->
            upper(item.Code default "") == "POR DEFECTO"
        )
    )[0] default {}

---
if (bancoEncontrado != null)
    bancoEncontrado
else
    bancoDefecto

%dw 2.0
output application/json skipNullOn="everywhere"

var pagoOnline = vars.responsePagosOnline.result[0] default {}

---
{
    requestHeader: {
        system: {
            name: "PAYMENT_MANAGEMENT_PAPI",
            correlationId: vars.idTransaccion,
            processingServer: "MULE"
        },
        properties: [
            {
                name: "source",
                value: "MULE"
            },
            {
                name: "channel",
                value: "MULESOFT"
            }
        ]
    },
    requestBody: {
        billingAccountNumber: pagoOnline.NumeroCuentaFacturacion default "",
        invoiceNumber: pagoOnline.NumeroFactura default "",
        rmcaInvoiceNumber: pagoOnline.NumeroFactura default "",
        collectedAmount: pagoOnline.ValorRecaudado default 0,
        collectionDate: pagoOnline.FechaRecaudo default "",
        collectingEntity: pagoOnline.EntidadRecaudadora default "",
        cycleNumber: pagoOnline.NumeroCiclo default "",
        collectingSystem: pagoOnline.SistemaRecaudador default "",
        paymentOrigin: pagoOnline.ProcedenciaPago default "",
        paymentMethod: pagoOnline.MetodoPago default "",
        collectingAccount: pagoOnline.CuentaRecaudadora default "",
        fileName: pagoOnline.ArchivoProcesamientoRMCA default "",
        collectingAccountType: pagoOnline.TipoCuentaRecaudadora default ""
    }
}

